import React from "react";
import { useNavigate } from "react-router-dom";
import { Carousel } from "react-responsive-carousel";
import "react-responsive-carousel/lib/styles/carousel.min.css";

function Sketches() {
  const navigate = useNavigate();

  const images2 = [
    "/bodyfacec1.avif",
    "/bodyfacec2.avif",
    "/bodyfacec3.avif",
    "/bodyfacec4.avif",
    "/bodyfacec5.avif",
    "/bodyfacec6.avif",
  ];

  const images = [
    "sketch1.avif",
    "sketch2.avif",
    "sketch3.avif",
    "sketch4.avif",
    "sketch5.avif",
    "sketch6.avif",
    "sketch7.avif",
    "sketch8.avif",
  ];
  const images22 = [
    "sketch21.avif",
    "sketch22.avif",
    "sketch23.avif",
    "sketch24.avif",
    "sketch25.avif",
  ];

  return (
    <>
      {/* Go Back Button */}
      <p
        className="underline text-base sm:text-lg md:text-xl lg:text-2xl cursor-pointer pl-5 mt-5"
        onClick={() => navigate(-1)}
      >
        Go Back
      </p>

      {/* Heading Section */}
      <div className="flex flex-col items-center justify-center mt-10">
        <h2 className="text-5xl font-bold text-red-500 text-center mt-2 mb-10">
          SKETCHES AND PAINTINGS
        </h2>
      </div>

      {/* Image Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-10 px-4 md:px-10 lg:px-20">
        {images.map((image, index) => (
          <img
            key={index}
            src={image}
            alt={`Sketch ${index + 1}`}
            className="shadow-lg mx-auto"
          />
        ))}
      </div>

      {/* Carousel Section */}
      <div className="flex justify-center items-center mt-10 px-20">
        <div className="w-full md:w-1/2">
          <Carousel
            autoPlay
            infiniteLoop
            showThumbs={false}
            showStatus={false}
            interval={3000}
            showArrows
          >
            {images2.map((image, index) => (
              <div key={index} className="flex justify-center">
                <img
                  src={image}
                  alt={`Design Slide ${index + 1}`}
                  className="rounded-lg mx-auto"
                />
              </div>
            ))}
          </Carousel>
        </div>
        <div>
        <h2 className="text-5xl font-bold text-blacktext-center mt-2 mb-10 ml-10">
        Body and Face Anatomy
        </h2>  
        <p className="text-2xl ml-10">I've been exploring the fascinating world of muscles and bones through sketches</p>  
        </div>

        <img src="/bodyface2.avif"/>
      </div>

      <div className="w-full md:w-1/2">
          <Carousel
            autoPlay
            infiniteLoop
            showThumbs={false}
            showStatus={false}
            interval={3000}
            showArrows
          >
            {images22.map((image, index) => (
              <div key={index} className="flex justify-center">
                <img
                  src={image}
                  alt={`Design Slide ${index + 1}`}
                  className="rounded-lg mx-auto"
                />
              </div>
            ))}
          </Carousel>

        <div>
        <h2 className="text-5xl font-bold text-blacktext-center mt-2 mb-10 ml-10">
        Perspective Understanding
        </h2>  
        <p className="text-2xl ml-10">Take a look at some of my drawings that play with depth and dimension.</p>  
        </div>

        <img src="/bodyface22.avif"/>
        </div>
    </>
  );
}

export default Sketches;
